/* K56flex's data-mode tables, per rate and pad (docs/history/k56-facts.md,
 * "Tables", "Data"). k56tab.c is generated by tools/gen_k56_tables.py and
 * says where its values come from (docs/limits.md, "Included tables
 * (K56flex)").
 *
 * Rate code r = 1..13: R = 30000 + 2000 r bit/s (32000 to 56000). Pad 0, 1,
 * 2: none, 3 dB, 6 dB, as the client's J reports it. */
#ifndef V90D_MODEM_K56TAB_H
#define V90D_MODEM_K56TAB_H
#include <stdint.h>

#define K56_NRATES 13

/* K shell-mapper bits a frame, u (u - 1 bits a symbol within its ring),
 * r the shaping period (every r-th symbol carries no sign bit), M rings
 * per pad. K + 8 (u - 1) + 8 - 8 / r = R / 1000. */
typedef struct { uint8_t K, u, r, M[3]; } k56_rate_t;

extern const k56_rate_t k56_rates[K56_NRATES];   /* index r - 1 */

/* The ring list of rate code `rate` and pad `pad`: M[pad] octets, the
 * constellation group of each shell-mapper ring m (cheapest first). */
const uint8_t *k56_ring(int rate, int pad);

/* The constellation: M[pad] << (u - 1) mu-law magnitude indices (0..127, 0
 * the smallest), one per point p = g << (u - 1) | q bits. */
const uint8_t *k56_bios(int rate, int pad);

#endif
